CREATE FUNCTION public.fi_create_farm_map(p_org uuid,p_name text,p_location text,p_fields jsonb) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT public.fi_import_farm(p_org,NULL,p_name,p_location,p_fields) $$; REVOKE ALL ON FUNCTION public.fi_create_farm_map(uuid,text,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fi_create_farm_map(uuid,text,text,jsonb) TO authenticated;